package lt.viko.eif.imazolevska.jaxws_client.runner;


import jakarta.xml.ws.WebServiceException;
import lt.viko.eif.imazolevska.jaxws.client.DirectorService;
import org.springframework.boot.CommandLineRunner;
import org.springframework.stereotype.Component;

/**
 * Checks on startup that the SOAP web service is reachable through the client
 * generated by wsimport, and prints the number of received directors.
 */
@Component
public class ClientRunner implements CommandLineRunner {

    private final DirectorService directorSoapClient;

    /**
     * Creates the runner.
     *
     * @param directorService SOAP client generated by wsimport
     */
    public ClientRunner(DirectorService directorService) {
        this.directorSoapClient = directorService;
    }

    /**
     * Calls the SOAP service and prints the result. Prints a warning instead of failing
     * if the server is not running.
     *
     * @param args command line arguments, not used
     */
    @Override
    public void run(String... args) {
        try {
            System.out.println("Directors received from SOAP service: "
                    + directorSoapClient.getAllDirectors().size());
        } catch (WebServiceException e) {
            System.out.println("SOAP service is not available: " + e.getMessage());
        }
    }
}